package br.com.inpetu.android;

import android.app.*;
import android.os.*;
import android.content.*;
import android.view.accessibility.*;
import android.graphics.Bitmap;
import org.json.*;
import java.io.*;
import java.time.*;
import java.util.*;

/** Instrumentação real sem bibliotecas externas e sem acesso à rede. Usa somente bancos descartáveis. */
public final class TestRunner extends Instrumentation {
 private final List<String> passed=new ArrayList<>();
 private int sequence=0;
 private Store db;
 interface Checked {void run() throws Exception;}
 private void yes(boolean v,String message){if(!v)throw new AssertionError(message);}
 private void denied(Checked run)throws Exception{try{run.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("Ação inválida foi aceita");}
 private Store fresh(String name){Store s=new Store(getTargetContext(),"test-"+(sequence++)+"-"+name+".db");s.setClock(Clock.fixed(Instant.parse("2026-10-05T15:00:00Z"),ZoneId.of("America/Sao_Paulo")));yes(s.login("bernardo","bernardo040"),"login do administrador");return s;}
 private JSONObject input(long space,String persona,String title)throws Exception{return new JSONObject().put("space",space).put("persona",persona).put("title",title).put("person","Pessoa de teste").put("cnpj","12345678000190").put("email","synthetic-private@example.com").put("phone","48999999999").put("company","Instituição teste").put("city","Cidade teste").put("day","2026-10-20").put("start",480).put("end",720).put("participants",10).put("paid",0).put("financed",0).put("academic",1);}
 private long space(){return db.saveSpace(null,"Sala de teste","40",true,true);}
 private void test(String name,Checked action)throws Exception{db=fresh(name);try{action.run();passed.add(name);}finally{db.close();}}
 @Override public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  test("cinco_logins_e_hashes",()->{for(int i=0;i<5;i++)yes(db.login(Store.LOGINS[i],Store.PASSWORDS[i]),"acesso de demonstração");yes(!db.login("bernardo","senha-errada"),"recusa de senha");yes(db.login(" BERNARDO ","bernardo040"),"normalização");for(JSONObject u:db.rows("SELECT length(hash) AS n FROM users"))yes(u.optInt("n")==32,"hash PBKDF2");});
  test("permissoes",()->{db.login("milena","milena040");denied(()->db.saveConfig(480,1200,4,0,0,0));space();db.logout();denied(()->space());});
  test("capacidade_e_correcao",()->{for(String cap:new String[]{"0","-1","0.5","1,5","2147483648"})denied(()->db.saveSpace(null,"Sala",cap,true,true));yes(db.spaces().isEmpty(),"cadastro inválido não persistiu");long id=space();denied(()->db.saveSpace(id,"Alteração inválida","0",false,false));yes(db.spaces().get(0).optInt("capacity")==40,"edição inválida preservou dados");db.saveSpace(id,"Alterada","25",false,true);yes(db.spaces().get(0).optInt("active")==0,"alteração persistiu");});
  test("agenda_vazia",()->yes(db.spaces().isEmpty()&&db.bookings(LocalDate.of(2026,10,20)).isEmpty(),"banco sem demonstrações ocupadas"));
  test("horarios_e_formatos",()->{long id=space();JSONObject b=input(id,"P6","Teste");b.put("participants",41);denied(()->db.createBooking(b));b.put("participants",10).put("start",479);denied(()->db.createBooking(b));b.put("start",480).put("end",480);denied(()->db.createBooking(b));b.put("end",720).put("day","2026-10-04");denied(()->db.createBooking(b));b.put("day","2027-10-06");denied(()->db.createBooking(b));b.put("day","2026-10-20").put("email","teste@a");denied(()->db.createBooking(b));b.put("email","synthetic-private@example.com").put("phone","abc12345");denied(()->db.createBooking(b));yes(db.bookings(LocalDate.of(2026,10,20)).isEmpty(),"invalidos não persistem");});
  test("conflito_apenas_aprovada",()->{long s=space();db.saveConfig(480,1200,4,0,0,0);long a=db.createBooking(input(s,"P6","Primeira")),b=db.createBooking(input(s,"P6","Segunda"));denied(()->db.approve(a,false));db.approve(a,true);denied(()->db.approve(b,true));yes(db.booking(b).optString("status").equals("PENDENTE"),"rollback de aprovação");JSONObject adjacent=input(s,"P6","Adjacente").put("start",720).put("end",960);db.approve(db.createBooking(adjacent),true);denied(()->db.createBooking(input(s,"P6","Conflito")));});
  test("taxas_explicitamente_configuradas",()->{long a=db.createBooking(input(space(),"P6","Sem taxas"));denied(()->db.approve(a,true));db.saveConfig(480,1200,4,0,0,0);db.approve(a,true);yes(db.booking(a).optLong("amount")==160000,"preço desktop 2026");yes(db.booking(a).optLong("deposit")==48000,"sinal de 30 por cento");});
  test("cota_cancelamento_penalidade",()->{db.saveConfig(480,1200,4,0,0,0);long id=db.createBooking(input(space(),"P2","Acadêmico"));yes(db.quota("P2",YearMonth.of(2026,10))[1]==0,"pendente não ocupa cota");db.approve(id,true);yes(db.quota("P2",YearMonth.of(2026,10))[1]==240,"aprovação usa quatro horas");yes(db.booking(id).optLong("amount")==0,"P2 acadêmico usa insumos configurados zero");db.cancel(id,"Cancelamento de teste",false);yes(db.quota("P2",YearMonth.of(2026,10))[1]==480,"penalidade de oito horas");});
  test("forca_maior_e_saldo_insuficiente",()->{db.saveConfig(480,1200,4,0,0,0);long id=db.createBooking(input(space(),"P4","Teste cota"));db.approve(id,true);db.cancel(id,"Interdição justificada",true);yes(db.quota("P4",YearMonth.of(2026,10))[1]==0,"força maior dispensa penalidade");db.saveQuota("P4",60);JSONObject next=input(db.spaces().get(0).optLong("id"),"P4","Sem saldo");long n=db.createBooking(next);db.approve(n,true);yes(db.booking(n).optInt("uses_quota")==0,"não usa cota insuficiente");});
  test("expiracao_e_recusa",()->{long a=db.createBooking(input(space(),"P6","Expiração"));denied(()->db.reject(a,""));db.setClock(Clock.fixed(Instant.parse("2026-10-07T15:00:00Z"),ZoneId.of("America/Sao_Paulo")));denied(()->db.approve(a,true));yes(db.booking(a).optString("status").equals("EXPIRADA"),"pendente expira");});
  test("pagamento_e_conclusao",()->{db.saveConfig(480,1200,4,0,0,0);long id=db.createBooking(input(space(),"P6","Pagamento"));denied(()->db.payment(id,"PAGO"));db.approve(id,true);db.payment(id,"SINAL_PAGO");denied(()->db.complete(id));db.setClock(Clock.fixed(Instant.parse("2026-10-20T18:00:00Z"),ZoneId.of("America/Sao_Paulo")));db.complete(id);yes(db.booking(id).optString("status").equals("CONCLUIDA"),"conclusão após fim");});
  test("logs_sem_dados_livres",()->{db.createBooking(input(space(),"P6","titulo-privado-nao-logar"));db.event("ERROR","SIMULATED_FAILURE",0,new IllegalStateException("senha-secreta-nao-logar"));String log=db.logExport();for(String secret:new String[]{"titulo-privado-nao-logar","synthetic-private@example.com","senha-secreta-nao-logar","bernardo040","12345678000190"})yes(!log.contains(secret),"privacidade do log");yes(log.contains(Store.VERSION)&&log.contains("IllegalStateException"),"diagnóstico com versão");});
  test("backup_restore_e_rollback",()->{long id=db.createBooking(input(space(),"P6","Persistente"));String data=db.backup();yes(!data.contains("hash")&&!data.contains("bernardo040"),"backup não exporta contas");Store restored=fresh("restore");try{denied(()->restored.restore("{\"schema\":1,\"platform\":\"android-offline\"}"));yes(restored.spaces().isEmpty(),"restauração inválida reverte");restored.restore(data);yes(restored.booking(id).optString("title").equals("Persistente"),"dados restaurados");denied(()->restored.restore(data));yes(restored.spaces().size()==1,"restauração não sobrescreve instalação");}finally{restored.close();}});
  test("persistencia_reabertura",()->{String name="test-reopen.db";getTargetContext().deleteDatabase(name);Store a=new Store(getTargetContext(),name);a.login("bernardo","bernardo040");a.saveSpace(null,"Persistente","25",true,true);a.close();Store b=new Store(getTargetContext(),name);try{yes(!b.logged(),"nova sessão exige login");yes(b.spaces().size()==1,"banco preservado no reinício");yes(b.login("bernardo","bernardo040"),"contas mantidas");}finally{b.close();}});
  test("taxacao_e_sinal",()->{yes(Rules.taxes("P1",false,true,false)[0]==0,"P1 isento");yes(Rules.taxes("P2",true,true,false)[0]==50,"P2 pago 50");yes(Rules.taxes("P3",true,true,false)[0]==75,"P3 pago 75");yes(Rules.taxes("P3",false,false,false)[0]==100,"fora da cota 100");yes(Rules.deposit(LocalDate.of(2026,10,25),false)==60,"domingo 60");yes(Rules.deposit(LocalDate.of(2026,10,20),true)==60,"feriado 60");yes(Rules.percent(105,50)==53,"arredondamento monetário");yes(!Rules.overlap(480,720,720,960),"limites adjacentes livres");});
  ui();passed.add("interface_login_cadastro_validacao");
  result.putString("stream","\nTESTES ANDROID APROVADOS: "+passed.size()+"\n"+new JSONArray(passed).toString()+"\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){try{shot("falha");AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();try(java.io.FileWriter w=new java.io.FileWriter(new File(getTargetContext().getExternalFilesDir(null),"test-falha-arvore.txt"))){tree(root,w,0);}}catch(Exception ignored){}result.putString("stream","\nCENARIOS APROVADOS: "+new JSONArray(passed)+"\nTESTES ANDROID FALHARAM: "+failure.getClass().getName()+" "+failure.getMessage()+"\n");finish(Activity.RESULT_CANCELED,result);}}
 private void tree(AccessibilityNodeInfo n,java.io.Writer w,int depth)throws Exception{if(n==null)return;w.write(depth+" "+n.getClassName()+" text="+n.getText()+" desc="+n.getContentDescription()+"\n");for(int i=0;i<n.getChildCount();i++)tree(n.getChild(i),w,depth+1);}
 private AccessibilityNodeInfo find(String text){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();return search(root,text);}
 private AccessibilityNodeInfo search(AccessibilityNodeInfo n,String text){if(n==null)return null;if(text.equalsIgnoreCase(n.getText()==null?"":n.getText().toString())||text.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo found=search(n.getChild(i),text);if(found!=null)return found;}return null;}
 private AccessibilityNodeInfo waitNode(String text)throws Exception{for(int i=0;i<240;i++){AccessibilityNodeInfo n=find(text);if(n!=null)return n;Thread.sleep(250);}throw new AssertionError("Tela não encontrada: "+text);}
 private void click(String text)throws Exception{AccessibilityNodeInfo n=waitNode(text);while(n!=null&&!n.isClickable())n=n.getParent();yes(n!=null&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK),"clique "+text);Thread.sleep(400);}
 private AccessibilityNodeInfo editable(AccessibilityNodeInfo n,String name){if(n==null)return null;if(n.isEditable()&&name.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo e=editable(n.getChild(i),name);if(e!=null)return e;}return null;}
 private void type(String name,String value)throws Exception{AccessibilityNodeInfo field=null;for(int i=0;i<120&&field==null;i++){field=editable(getUiAutomation().getRootInActiveWindow(),name);if(field==null)Thread.sleep(250);}yes(field!=null,"campo "+name);Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);yes(field.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b),"preencher "+name);}
 private void shot(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();yes(b!=null,"captura da tela");File f=new File(getTargetContext().getExternalFilesDir(null),"test-"+name+".png");try(OutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void ui()throws Exception{Intent i=new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivitySync(i);waitNode("Área interna");shot("login");type("Login *","bernardo");type("Senha *","bernardo040");click("Entrar");waitNode("Agenda local");shot("agenda");click("Espaços");click("Cadastrar espaço");type("Nome do espaço *","Sala do emulador");type("Capacidade (inteiro positivo) *","0");click("Salvar espaço");waitNode("Confira os dados");shot("validacao");click("Entendi");yes(find("Nome do espaço *")!=null,"formulário preservado");type("Capacidade (inteiro positivo) *","25");click("Salvar espaço");waitNode("Sala do emulador · 25 pessoas");shot("espacos");}
}
